import time, random

# PULL: client owns the clock. Server stays stateless.
# Trade-off: simple, but QPS scales with clients, not events.
def pull_loop(fetch, cursor=None):
    backoff = 1.0
    while True:
        items, cursor = fetch(since=cursor)  # idempotent GET
        if items:
            backoff = 1.0
            process(items)
        else:
            time.sleep(backoff + random.uniform(0, 0.5))
            backoff = min(backoff * 2, 30.0)  # jittered backoff sheds load

# PUSH: server owns delivery. Must track subscriptions + resume point.
# Trade-off: instant, but server holds state per subscriber.
subscriptions: dict[str, dict] = {}  # conn_id -> {filter, last_id, alive_ts}
RETAIN = 1000  # bounded replay buffer; older than this = resync from snapshot
log: list[tuple[int, object]] = []

def on_subscribe(conn_id, filter_, last_seen_id):
    subscriptions[conn_id] = {"filter": filter_, "last_id": last_seen_id, "alive_ts": time.time()}
    replay(conn_id, since=last_seen_id)  # catch-up or snapshot if too far behind

def on_event(event, seq):
    log.append((seq, event))
    del log[:-RETAIN]  # bound memory: trade completeness for survival
    for cid, sub in list(subscriptions.items()):
        if matches(sub["filter"], event):
            deliver_at_least_once(cid, seq, event)  # receiver must dedup by seq
